// TH16 v1.00a Stage 4 boss non-spell: st04bs.ecl.txt Boss3 (lines 290-352).
// Segment window: timerReset(302)/setInterrupt(323) .. 1800-frame timeout (BossCard3 takes over).
// Target timing: 120-frame shell buffer + 1800 source frames + 4 startup margin.

const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;

const TH16_TALISMAN: int = 528;   // source etSprite type 11 (bullet-types.md)

// ---------------------------------------------------------------------------
// Movement: source moveRand(412) recipe (movement.md), limit box moveLimit(0,128,280,96).
// Box: x in [-140,140], y in [80,176]; direction inner zone x +/-70, y 104..152.
// Shared slots: int0 = step k, int1 = duration, fx0/fx1 = unit direction, fx2 = start speed.
// ---------------------------------------------------------------------------
sub mv_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var total: int = self_int(1);
    var speed: fx = 0fx;
    if k < total { speed = self_fx(2) * ((total - k) as fx / total); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mv_direction() {
    // One direction sample per call; values are unwrapped BAM ints, normalised only at cast.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
}

sub mv_begin(total: int, speed0: fx) {
    set_self_int(1, total);
    set_self_fx(2, speed0);
    mv_direction();
    mv_step();
}

sub mv_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mv_step();
    }
}

// ---------------------------------------------------------------------------
// Bullet EX: ANIM(2,a=1) birth stage omitted; its position-=4*velocity retreat is folded
// into sh_dist below. OFFSCREEN(256,a=240,b=0) -> offscreen_keep. ANGLE_ACCEL(8,a=120)
// -> set_ang_vel + set_accel for 120 frames, then both zeroed.
// 240 source handler decrements minus the ANIM/ANGLE_ACCEL end re-runs (2) -> 238.
// ---------------------------------------------------------------------------
xformdef CURVE_ACCEL(ang_vel: angle, accel: fx) {
    offscreen_keep(238);
    set_ang_vel(ang_vel);
    @120 set_accel(accel);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// source Boss3_at(A, B, C, D): B=color, C=burst-to-burst base angle step, D=curve rate.
async sub boss3_at(color: int, burst_step: angle, curve_base: angle) {
    var ways: int = 9;                        // source !E 9 / !N 15 / !H 19 / !LO 19
    if global(GVAR_RANK) == RANK_NORMAL { ways = 15; }
    if global(GVAR_RANK) >= RANK_HARD { ways = 19; }
    var ang_vel: angle = curve_base;          // !E/!N/!H: D;  !LO: D*1.2
    var accel: fx = 0.02fx;                   // !E/!N/!H: 0.02; !LO: 0.025
    if global(GVAR_RANK) >= RANK_LUNATIC {
        ang_vel = ((curve_base as int) * 6 / 5) as angle;
        accel = 0.025fx;
    }
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, color);       // etSprite(11, color)
    sh_ring(0, 1);                            // etAim mode 3: fixed-direction full ring
    sh_aim(0, 0);
    sh_count(0, ways, 1);                     // etCount(ways, 1); etAngle's 2deg spread is layer-only and unused at M=1
    sh_speed(0, 0.5fx, 0fx);                  // etSpeed(0.5, 1.0), M=1 keeps s0
    sh_offset(0, 0fx, -16fx);                 // etOffset(0, -16)
    sh_dist(0, 30fx);                         // etDist 32 - 4 * 0.5 birth ANIM retreat
    sh_xform(0, CURVE_ACCEL(ang_vel, accel));
    var base: angle = 90deg;                  // %E = pi/2
    for i in 0..5 {                           // $F = 5 bursts, 10 frames apart
        sh_angle(0, base, 0deg);
        sh_fire(0);
        base = base + burst_step;
        wait(10);
    }
}

// ---------------------------------------------------------------------------
// Source Boss3 main task. Handover-only work is not reproduced for the standalone card:
// etCancel/etClear(640), killAllAsync, enmKillAll, laserCancel, spellEnd, funcSet(0),
// lifeMarker/stars/dropSeason/drop config and the anm/playSound calls start from a clean
// field here (transcription-policy: segment handover and presentation are omitted).
// ---------------------------------------------------------------------------
async sub boss3_main() {
    set_invuln(65535);                        // shell invulnerability (source setInvuln(120))
    set_hurtbox(20fx);                        // Boss(): setHurtbox(40,40) -> r=20
    set_hitbox(24fx);                         // Boss(): setHitbox(48,48) -> r=24
    // source moveVel(0,0) / moveVelTime(0,...) / movePosTime(0,...): spawned at rest
    wait(60);                                 // source wait(60) between declaration ANMs
    wait(60);                                 // source wait(60)
    loop {
        mv_begin(240, 0.5fx);                 // Boss3_1144: moveRand(240, 4, 0.5)
        for i in 0..3 {                       // $A = 3 pairs
            spawn boss3_at(2, 2deg, 1deg);    // Boss3_at(0, 2, +2deg, +1deg) async
            mv_wait(25);
            spawn boss3_at(4, -2deg, -1deg);  // Boss3_at(1, 4, -2deg, -1deg) async
            mv_wait(25);
        }
        // Boss3:348 moveRand(60, 4, 1.0) and the loop-head moveRand(240, 4, 0.5) run in the
        // same frame (jump @0 costs none), so the 60-frame move is superseded immediately;
        // it is kept for its direction sample and ordering.
        mv_begin(60, 1fx);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 15300, 0, 0, 0, boss3_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);   // segment end: the source boss hands over to BossCard3
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
